# Source this file: `source test/fixture/env.sh`
# Fixture settings for the bw-wrapper differential tests. Never points at the
# real vault in ~/.config/Bitwarden CLI.

# bw >= 2026.x refuses plain-HTTP servers, so the fixture serves TLS with a
# throwaway CA generated by up.sh. NODE_EXTRA_CA_CERTS makes the real bw trust it.
export BWW_FIXTURE_URL=https://127.0.0.1:18087
export BWW_FIXTURE_ROOT=/tmp/bww-fixture
BWW_FIXTURE_HELPERS=$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)
export BWW_FIXTURE_HELPERS
export BWW_FIXTURE_CA=$BWW_FIXTURE_ROOT/tls/ca.pem
export NODE_EXTRA_CA_CERTS=$BWW_FIXTURE_CA
export BWW_CONTAINER=bww-test-vaultwarden
export BWW_VOLUME=bww-test-vw-data
# The real Bitwarden CLI: REAL_BW if set, else the first `bw` on PATH that is
# not bw-wrapper's own link.
if [ -z "${REAL_BW:-}" ]; then
  for _bw in $(type -ap bw 2>/dev/null); do
    case "$(readlink -f "$_bw")" in
      */bw-wrapper) ;;
      *) REAL_BW=$_bw; break ;;
    esac
  done
  unset _bw
fi
[ -n "${REAL_BW:-}" ] || echo "env.sh: no real Bitwarden CLI found on PATH; set REAL_BW" >&2
export REAL_BW

export ALICE_EMAIL=alice@example.test
export ALICE_PW=alice-master-pw-1
export ALICE_APPDATA=$BWW_FIXTURE_ROOT/alice
export BOB_EMAIL=bob@example.test
export BOB_PW=bob-master-pw-1
export BOB_APPDATA=$BWW_FIXTURE_ROOT/bob

# Run the real bw against a fixture account: fixture_bw alice|bob ARGS...
# Refuses to run unless the app-data dir is a fixture dir.
fixture_bw() {
  local who=$1; shift
  local dir
  case $who in
    alice) dir=$ALICE_APPDATA ;;
    bob) dir=$BOB_APPDATA ;;
    *) echo "fixture_bw: unknown account '$who'" >&2; return 2 ;;
  esac
  # resolved first: ".." or a symlink must not lead out of the fixture
  dir=$(python3 -c 'import sys; sys.path.insert(0, sys.argv[1]); import safety; print(safety.fixture_path(sys.argv[2]))' \
        "$BWW_FIXTURE_HELPERS" "$dir") || { echo "fixture_bw: refusing app-data dir" >&2; return 2; }
  BITWARDENCLI_APPDATA_DIR=$dir NODE_EXTRA_CA_CERTS=$BWW_FIXTURE_CA "$REAL_BW" "$@"
}

# Print a fresh session key for alice|bob via the real bw.
fixture_unlock() {
  local who=$1 pwvar
  case $who in
    alice) pwvar=ALICE_PW ;;
    bob) pwvar=BOB_PW ;;
    *) echo "usage: fixture_unlock alice|bob" >&2; return 2 ;;
  esac
  fixture_bw "$who" unlock --passwordenv "$pwvar" --raw --nointeraction
}
